-- Factual summary storage, and the NVC-0101 case update.
--
-- Adds the structured case fields and the insert-only document table the
-- factual summary reads. Seeds Kimberly Harper / Kevin (booking
-- 085d3e27-c421-4b1d-9280-c2eafe31d983) from the messages and the two PDFs the client sent.
-- Append-only: existing timeline text, the manager account, the contractor
-- statement, and the client written communication are not assigned here.
-- Insurance stays pending unless a notification timestamp was already stored.
-- Re-running is a no-op once the escalation event is present. If the case
-- row does not exist yet, the seed is skipped.

ALTER TABLE public.qc_issues
  ADD COLUMN IF NOT EXISTS contractor_position jsonb,
  ADD COLUMN IF NOT EXISTS client_position jsonb,
  ADD COLUMN IF NOT EXISTS medical_record_review jsonb,
  ADD COLUMN IF NOT EXISTS escalation jsonb,
  ADD COLUMN IF NOT EXISTS insurance_notification jsonb NOT NULL
    DEFAULT '{"status":"pending","notified_at":null,"method":null,"carrier_response":null}'::jsonb,
  ADD COLUMN IF NOT EXISTS correspondence_log jsonb NOT NULL DEFAULT '[]'::jsonb,
  ADD COLUMN IF NOT EXISTS generated_case_documents jsonb NOT NULL DEFAULT '[]'::jsonb;

COMMENT ON COLUMN public.qc_issues.contractor_position IS
  'Structured contractor position already captured on the case. Not a finding.';
COMMENT ON COLUMN public.qc_issues.client_position IS
  'Structured client position and written payment requests. Not a finding.';
COMMENT ON COLUMN public.qc_issues.medical_record_review IS
  'Structured notes of what a medical record records, rules out, and does not establish. Not a fault conclusion.';
COMMENT ON COLUMN public.qc_issues.escalation IS
  'Logged legal-threat flag: forum, method, timestamp, and demand already stated. Not a filing.';
COMMENT ON COLUMN public.qc_issues.insurance_notification IS
  'Pending until a person records that the carrier was notified and stores the date. A sentence in an email does not complete this field.';
COMMENT ON COLUMN public.qc_issues.correspondence_log IS
  'Messages logged on the case. Append-only. Each body is that message, not the quoted thread.';
COMMENT ON COLUMN public.qc_issues.generated_case_documents IS
  'Factual summaries generated from this case. Append-only. Retained with the case.';

-- A stored notification date is the only thing that counts as notified.
UPDATE public.qc_issues
SET insurance_notification = jsonb_build_object(
  'status', 'notified',
  'notified_at', insurance_notified_at,
  'method', insurance_notification->'method',
  'carrier_response', insurance_notification->'carrier_response'
)
WHERE insurance_notified_at IS NOT NULL
  AND COALESCE(insurance_notification->>'status', '') IS DISTINCT FROM 'notified';

CREATE OR REPLACE FUNCTION public.qc_jsonb_preserve_entries(old_rows jsonb, new_rows jsonb)
RETURNS jsonb
LANGUAGE plpgsql
STABLE
SET search_path = public
AS $preserve$
DECLARE
  result jsonb := CASE
    WHEN old_rows IS NULL OR jsonb_typeof(old_rows) <> 'array' THEN '[]'::jsonb
    ELSE old_rows
  END;
  item jsonb;
  item_id text;
  item_key text;
BEGIN
  IF new_rows IS NULL OR jsonb_typeof(new_rows) <> 'array' THEN
    RETURN result;
  END IF;

  FOR item IN SELECT value FROM jsonb_array_elements(new_rows)
  LOOP
    item_id := NULLIF(btrim(COALESCE(item->>'id', '')), '');
    item_key := concat_ws(
      '|',
      COALESCE(item->>'kind', ''),
      COALESCE(item->>'filename', ''),
      COALESCE(NULLIF(item->>'received_at', ''), NULLIF(item->>'at', ''), ''),
      COALESCE(
        NULLIF(item->>'description', ''),
        NULLIF(item->>'objective_description', ''),
        NULLIF(item->>'subject', ''),
        ''
      )
    );
    IF item_id IS NOT NULL AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(result) prev
      WHERE NULLIF(btrim(COALESCE(prev->>'id', '')), '') = item_id
    ) THEN
      CONTINUE;
    END IF;
    IF item_key IS DISTINCT FROM '|||' AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(result) prev
      WHERE concat_ws(
        '|',
        COALESCE(prev->>'kind', ''),
        COALESCE(prev->>'filename', ''),
        COALESCE(NULLIF(prev->>'received_at', ''), NULLIF(prev->>'at', ''), ''),
        COALESCE(
          NULLIF(prev->>'description', ''),
          NULLIF(prev->>'objective_description', ''),
          NULLIF(prev->>'subject', ''),
          ''
        )
      ) = item_key
    ) THEN
      CONTINUE;
    END IF;
    IF EXISTS (
      SELECT 1 FROM jsonb_array_elements(result) prev
      WHERE prev = item
    ) THEN
      CONTINUE;
    END IF;
    result := result || jsonb_build_array(item);
  END LOOP;
  RETURN result;
END;
$preserve$;

REVOKE ALL ON FUNCTION public.qc_jsonb_preserve_entries(jsonb, jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.qc_jsonb_preserve_entries(jsonb, jsonb) TO service_role;

CREATE OR REPLACE FUNCTION public.qc_preserve_case_record()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $preserve_trg$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    NEW.client_followup_documents := public.qc_jsonb_preserve_entries(OLD.client_followup_documents, NEW.client_followup_documents);
    NEW.correspondence_log := public.qc_jsonb_preserve_entries(OLD.correspondence_log, NEW.correspondence_log);
    NEW.generated_case_documents := public.qc_jsonb_preserve_entries(OLD.generated_case_documents, NEW.generated_case_documents);
    IF OLD.retain_permanently IS TRUE THEN
      NEW.retain_permanently := true;
    END IF;
    IF OLD.admin_only IS TRUE THEN
      NEW.admin_only := true;
    END IF;
  END IF;
  RETURN NEW;
END;
$preserve_trg$;

DROP TRIGGER IF EXISTS qc_preserve_case_record_trg ON public.qc_issues;
CREATE TRIGGER qc_preserve_case_record_trg
  BEFORE UPDATE ON public.qc_issues
  FOR EACH ROW EXECUTE FUNCTION public.qc_preserve_case_record();

CREATE TABLE IF NOT EXISTS public.qc_issue_documents (
  id text PRIMARY KEY,
  issue_id uuid NOT NULL REFERENCES public.qc_issues(id) ON DELETE RESTRICT,
  kind text,
  filename text,
  mime_type text,
  source text,
  received_at timestamptz,
  objective_description text,
  content_text text,
  sha256 text,
  byte_size integer,
  pdf_base64 text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS qc_issue_documents_issue_idx
  ON public.qc_issue_documents (issue_id, created_at);

COMMENT ON TABLE public.qc_issue_documents IS
  'Original files attached to a QC case. Insert-only. Bytes live here so a qc_issues list does not load them.';

CREATE OR REPLACE FUNCTION public.qc_issue_documents_immutable()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $docs_immutable$
BEGIN
  RAISE EXCEPTION 'qc_issue_documents rows are immutable';
END;
$docs_immutable$;

DROP TRIGGER IF EXISTS qc_issue_documents_no_update ON public.qc_issue_documents;
CREATE TRIGGER qc_issue_documents_no_update
  BEFORE UPDATE ON public.qc_issue_documents
  FOR EACH ROW EXECUTE FUNCTION public.qc_issue_documents_immutable();

DROP TRIGGER IF EXISTS qc_issue_documents_no_delete ON public.qc_issue_documents;
CREATE TRIGGER qc_issue_documents_no_delete
  BEFORE DELETE ON public.qc_issue_documents
  FOR EACH ROW EXECUTE FUNCTION public.qc_issue_documents_immutable();

ALTER TABLE public.qc_issue_documents ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS qc_issue_documents_admin_read ON public.qc_issue_documents;
CREATE POLICY qc_issue_documents_admin_read ON public.qc_issue_documents
  FOR SELECT TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.qc_issues i
      WHERE i.id = qc_issue_documents.issue_id
        AND public.is_admin_or_va(auth.uid())
        AND (
          COALESCE(i.admin_only, false) = false
          OR public.has_role(auth.uid(), 'admin'::app_role)
        )
    )
  );

DROP POLICY IF EXISTS qc_issue_documents_service_role ON public.qc_issue_documents;
CREATE POLICY qc_issue_documents_service_role ON public.qc_issue_documents
  FOR ALL TO service_role
  USING (true) WITH CHECK (true);

GRANT SELECT ON public.qc_issue_documents TO authenticated;
GRANT ALL ON public.qc_issue_documents TO service_role;

DO $seed$
DECLARE
  v_issue uuid;
  v_prev_status text;
  v_ack text;
  v_records text;
  v_close text;
  v_claims text;
  v_record_text text;
  v_invoice_text text;
  v_record_desc text;
  v_invoice_desc text;
  v_record_pdf text;
  v_invoice_pdf text;
  v_note text;
BEGIN
  SELECT q.id, q.status INTO v_issue, v_prev_status
  FROM public.qc_issues q
  WHERE q.booking_id = '085d3e27-c421-4b1d-9280-c2eafe31d983'
    AND q.issue_type = 'serious_allegation'
  ORDER BY q.created_at
  LIMIT 1;

  IF v_issue IS NULL THEN
    RAISE NOTICE 'NVC-0101 serious-allegation case is not present; record seed skipped.';
    RETURN;
  END IF;

  v_ack := $ackbody$Kimberly,

Thank you for taking the time to write this out in detail. I'm sorry your experience with us was anything other than what you needed, and I'm genuinely sorry to hear about Kevin. I understand you spent the night at an emergency vet, and with your surgery Thursday, the timing could not be worse. That matters to me.

I want to respond to everything you raised directly.

On Kevin. I take an allegation like this extremely seriously. I've opened a formal incident investigation, requested a written statement from the contractor, and notified our insurance carrier so it can be reviewed properly. The contractor has given an account that conflicts with yours. I wasn't present, and as far as I'm aware there were no other witnesses, so I'm not going to state conclusions to you that I can't support in either direction. Please do send the veterinary records and invoice when you have them. I want the full picture.

One detail for accuracy: I was the person you spoke with by phone, and I asked the contractor to leave — no one from our team was physically at your home. I note it only so our records are accurate, not to diminish anything you've raised.

On the service. Separate from the above, several things you described are simply not our standard, and I'm not going to defend them:

- Arriving over 30 minutes late is not acceptable.
- Not knowing the checklist is not acceptable. Every job has a defined room-by-room checklist, and a cleaner should be able to tell you exactly what it covers without you having to explain it.
- Extended unaccounted time mid-job is not acceptable.
- Appearance and professionalism standards apply on every job, without exception.
- Leaving rooms started but unfinished, and leaving your home requiring work from you afterward, is the opposite of why you hired us.

On the furniture: my understanding is that it was moved at your request to clean behind it. I say that only for accuracy; the cleaner should have returned everything to position and communicated with you before leaving, and that didn't happen. That's on us regardless of who asked for what. We are currently reviewing the before videos captured on the job.

Next steps. The contractor involved is not being assigned further work while this is under investigation. I'll follow up once the investigation is complete and the veterinary records are in.

I'd like the chance to make the service part right, but you're about to have surgery — so I'd rather follow your lead on timing than push.

You can reach me directly at (844) 735-2070 or by replying here.

Malik Sannie
NovaraCleaning, LLC
$ackbody$;
  v_records := $recordsbody$Good Morning Malik,

Sorry this has taken a few days to get over to you.  Surgery and recovery
have been a bit harder than I anticipated.  Here is Kevins medical record
and invoice.  You can pay VeG directly.  In addition to his invoice, I am
requesting $1000 for my time, stress, gas money and incidentals along with
the emotional roller coaster that working with your company brought me,
especially on the eve of having major spinal surgery.  My furniture was
moved at my request - yes, but I also thought this was something standard
with a deep clean.  Since your contractor didn't know the
company's checklist for each room, how was I supposed to know?  Thankfully
a friend was able to stop by on his way home and return my house to how it
should have been before Fiona left.
While I appreciate your offer to make things right service wise, I'd much
rather cut my losses and walk away after being made whole.  I am normally
all for giving mom & pop small businesses my dollars.  But hiring a
business to work on my house should not end with me spending more money
than planned to redo the job your company failed to finish.  Plus emergency
veterinary bills.
Please pay Kevins bill ASAP.

Thank you,
Kimberly
$recordsbody$;
  v_close := $closebody$Kimberly,

I wanted to follow up and close the loop on this.

I've now reviewed Kevin's full record closely. I want to be direct with
you: nothing in the records identifies what caused the swelling, and
nothing in them confirms it resulted from a person striking him. The
radiology report lists a few possible explanations, including inflammation
and hemorrhage, but does not point to a specific cause or a specific source.

I take what happened to Kevin seriously, and I'm glad he's recovering. But
I'm not able to make a finding connecting this to anyone on our team based
on what the records actually show, and I don't think it would be fair to
either of us for me to imply otherwise.

I don't have anything further to add on the incident itself, so I want to
close this out honestly here.

I hope your recovery from surgery is going well, and I hope Kevin continues
to heal.

Malik

NovaraCleaning, LLC
$closebody$;
  v_claims := $claimsbody$Would you like to go to small claims court?  That’s my next step with you.
